<?php
$kp = sodium_crypto_sign_seed_keypair(str_repeat("S", 32)); $sk = sodium_crypto_sign_secretkey($kp); $pk = sodium_crypto_sign_publickey($kp); echo bin2hex($kp), " "; $sig = sodium_crypto_sign_detached("message\0x", $sk); echo bin2hex($sig), " "; var_dump(sodium_crypto_sign_verify_detached($sig, "message\0x", $pk), sodium_crypto_sign_verify_detached($sig, "message\0y", $pk)); $sm = sodium_crypto_sign("hello", $sk); echo bin2hex($sm), " ", sodium_crypto_sign_open($sm, $pk); var_dump(sodium_crypto_sign_open("x" . $sm, $pk)); echo bin2hex(sodium_crypto_sign_publickey_from_secretkey($sk)), " ", bin2hex(sodium_crypto_sign_keypair_from_secretkey_and_publickey($sk, $pk)) === bin2hex($kp) ? "same" : "diff";
